#include "mod_api.h"
#include "mod_state.h"

static const BwModHost *g_host;
static int g_given;

static int on_route(void *mod, BwEvent *event)
{
    BwRouteChange *e = (BwRouteChange *)event;
    (void)mod;
    if (e->zone == 115 && !g_given && g_host->state->item_add(17, 5) == 0) {
        g_given = 1;
    }
    return BW_EVENT_CONTINUE;
}

