#include "mod_api.h"
#include "mod_state.h"

static const BwModHost *g_host;
static u32 g_faints;

static int on_faint(void *mod, BwEvent *event)
{
    BwBattleFaint *e = (BwBattleFaint *)event;
    char line[24] = "Faints: ";
    char digits[11];
    u32 n = 0, v, i;
    (void)mod;
    if (e->side != 0) {
        return BW_EVENT_CONTINUE;
    }
    g_faints++;
    v = g_faints;
    do {
        digits[n++] = (char)('0' + v % 10);
        v /= 10;
    } while (v);
    for (i = 0; i < n; i++) {
        line[8 + i] = digits[n - 1 - i];
    }
    line[8 + n] = 0;
    g_host->services->panel_set(0, line);
    return BW_EVENT_CONTINUE;
}

int eidos_mod_start(const BwModHost *host, void **mod_state)
{
    g_host = host;
    *mod_state = 0;
    return host->on(BW_EVENT_BATTLE_FAINT, on_faint);
}

void eidos_mod_stop(void *mod_state)
{
    (void)mod_state;
}

#include "mod_api.h"
#include "mod_state.h"

static const BwModHost *g_host;

static int on_exp(void *mod, BwEvent *event)
{
    BwMonExp *e = (BwMonExp *)event;
    s32 cap = 100;
    (void)mod;
    g_host->services->table_get("caps", (s32)g_host->state->badge_count(), &cap);
    if ((s32)e->level >= cap) {
        e->amount = 0;
    }
    return BW_EVENT_CONTINUE;
}

int eidos_mod_start(const BwModHost *host, void **mod_state)
{
    g_host = host;
    *mod_state = 0;
    return host->on(BW_EVENT_MON_EXP, on_exp);
}

void eidos_mod_stop(void *mod_state)
{
    (void)mod_state;
}
